import java.util.HashSet;
import java.util.Set;

class Solution {
    public int findFinalValue(int[] nums, int original) {
        Set<Integer> values = new HashSet<>();
        for (int num : nums) {
            values.add(num);
        }
        while (values.contains(original)) {
            original *= 2;
        }
        return original;
    }
}

import java.util.Arrays;

class Solution {
    public int findFinalValue(int[] nums, int original) {
        Arrays.sort(nums);
        for (int num : nums) {
            if (num == original) {
                original *= 2;
            }
        }
        return original;
    }
}

class Solution {
    public int findFinalValue(int[] nums, int original) {
        boolean[] present = new boolean[1001];
        for (int num : nums) {
            present[num] = true;
        }
        while (original <= 1000 && present[original]) {
            original *= 2;
        }
        return original;
    }
}

import java.util.Arrays;

class Solution {
    public int findFinalValue(int[] nums, int original) {
        Arrays.sort(nums);
        while (Arrays.binarySearch(nums, original) >= 0) {
            original *= 2;
        }
        return original;
    }
}
